-- Source: FED_CMS_NURSING_HOME_PENALTIES (16180 rows)
-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: PENALTY_DATE, FINE_AMOUNT, PAYMENT_DENIAL_START_DATE and
-- PROCESSING_DATE were bare try_to_date()/try_to_double() -- unguarded, so a
-- pure-digit date could misread as epoch seconds and a decimal fine amount
-- could poison on a stray 'nan'. A matching staging model exists
-- (stg_fed_cms_nursing_home_penalties__facilities) but leaves the three date
-- columns as TEXT and casts FINE_AMOUNT to a whole-number int, both
-- different types than this mart wants (dates, and a decimal-preserving
-- float for a dollar amount) -- swapping to ref() would silently change
-- those columns' types, so this stays on source() and only the bare casts
-- are wrapped (macros/staging_casts.sql): stg_date for the three dates,
-- stg_float for FINE_AMOUNT (a dollar figure can carry cents; stg_int would
-- round them off). PAYMENT_DENIAL_LENGTH_IN_DAYS was already guarded via
-- ripple_num and is unchanged.

with source as (
    select * from {{ source('ripple_raw', 'FED_CMS_NURSING_HOME_PENALTIES') }}
)

select
    CMS_CERTIFICATION_NUMBER_CCN as cms_certification_number_ccn,
    PROVIDER_NAME as provider_name,
    PROVIDER_ADDRESS as provider_address,
    CITY_TOWN as city_town,
    STATE as state,
    ZIP_CODE as zip_code,
    {{ stg_date('PENALTY_DATE') }} as penalty_date,
    PENALTY_TYPE as penalty_type,
    FINE_ID as fine_id,
    {{ stg_float('FINE_AMOUNT') }} as fine_amount,
    {{ stg_date('PAYMENT_DENIAL_START_DATE') }} as payment_denial_start_date,
    {{ ripple_num('PAYMENT_DENIAL_LENGTH_IN_DAYS') }} as payment_denial_length_in_days,
    LOCATION as location,
    {{ stg_date('PROCESSING_DATE') }} as processing_date
from source
